	if worktreePath == "" {
		return repoUnknown
	}
	cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "remote", "get-url", "origin") //nolint:gosec // path comes from session state written by the CLI
	raw, err := cmd.Output()
	if err != nil {
		return repoUnknown
	}
	info, err := gitremote.ParseURL(strings.TrimSpace(string(raw)))
	if err != nil || info == nil || info.Owner == "" || info.Repo == "" {
		return repoUnknown
	}
	return info.Owner + "/" + info.Repo
}

