package recap

import "github.com/charmbracelet/lipgloss"

// Palette colors. Reuse the same lipgloss.Color values as search_tui.go,
// status_style.go, and PR #999's activity_render.go so the recap view feels
// like it belongs to the CLI rather than a foreign body.
const (
	colorAccent    = "214" // amber — panel titles, agent names
	colorMuted     = "8"   // dark gray — labels, units
	colorHelpKey   = "245" // slightly brighter gray for key cues
	colorHelpSep   = "241" // dim gray for separators in help line
	colorBorder    = "243" // panel borders
	colorAdd       = "2"   // green — push / additions
	colorDel       = "1"   // red — destructive
	colorWarn      = "3"   // yellow — clean
	colorInfo      = "6"   // cyan — resume
	colorNeutral   = "7"   // light gray — default body
	colorAccentDim = "240" // dim amber for faded accents
)

// recapStyles holds pre-built lipgloss styles by semantic role. Declaring
// roles (not colors) lets rendering code say `styles.accent.Render(name)`
// without caring which Pantone chip is active — and lets us retune the
// whole palette in one place.
type recapStyles struct {
	bold   lipgloss.Style
	dim    lipgloss.Style
	label  lipgloss.Style
	value  lipgloss.Style
	unit   lipgloss.Style
	title  lipgloss.Style
	accent lipgloss.Style
	border lipgloss.Style
	add    lipgloss.Style
	del    lipgloss.Style
	warn   lipgloss.Style
	info   lipgloss.Style
	muted  lipgloss.Style
	help   lipgloss.Style
	key    lipgloss.Style

	// hintResume/Commit/Push/Clean map the ActionHint values to styles so
	// the session list renders consistent colors without a switch at each
	// call site.
	hintResume lipgloss.Style
	hintCommit lipgloss.Style
	hintPush   lipgloss.Style
	hintClean  lipgloss.Style
}

// newRecapStyles returns a style set. When useColor is false (piped stdout,
// ACCESSIBLE=1), every style becomes a no-op so rendered output contains
// no ANSI escapes.
func newRecapStyles(useColor bool) recapStyles {
	if !useColor {
		return recapStyles{} // all zero-value lipgloss.Style → plain text
	}
	return recapStyles{
		bold:       lipgloss.NewStyle().Bold(true),
		dim:        lipgloss.NewStyle().Faint(true),
		label:      lipgloss.NewStyle().Foreground(lipgloss.Color(colorMuted)).Bold(true),
		value:      lipgloss.NewStyle().Bold(true),
		unit:       lipgloss.NewStyle().Foreground(lipgloss.Color(colorMuted)),
		title:      lipgloss.NewStyle().Foreground(lipgloss.Color(colorAccent)).Bold(true),
		accent:     lipgloss.NewStyle().Foreground(lipgloss.Color(colorAccent)),
		border:     lipgloss.NewStyle().Foreground(lipgloss.Color(colorBorder)),
		add:        lipgloss.NewStyle().Foreground(lipgloss.Color(colorAdd)),
		del:        lipgloss.NewStyle().Foreground(lipgloss.Color(colorDel)),
		warn:       lipgloss.NewStyle().Foreground(lipgloss.Color(colorWarn)),
		info:       lipgloss.NewStyle().Foreground(lipgloss.Color(colorInfo)),
		muted:      lipgloss.NewStyle().Foreground(lipgloss.Color(colorMuted)),
		help:       lipgloss.NewStyle().Foreground(lipgloss.Color(colorHelpSep)),
		key:        lipgloss.NewStyle().Foreground(lipgloss.Color(colorHelpKey)).Bold(true),
		hintResume: lipgloss.NewStyle().Foreground(lipgloss.Color(colorInfo)),
		hintCommit: lipgloss.NewStyle().Foreground(lipgloss.Color(colorAccent)),
		hintPush:   lipgloss.NewStyle().Foreground(lipgloss.Color(colorAdd)),
		hintClean:  lipgloss.NewStyle().Foreground(lipgloss.Color(colorWarn)),
	}
}

// styleForHint returns the style that renders a given ActionHint. Returns a
// zero Style (plain) for ActionNone so callers don't have to handle nil.
func (s recapStyles) styleForHint(h ActionHint) lipgloss.Style {
	switch h {
	case ActionResume:
		return s.hintResume
	case ActionCommit:
		return s.hintCommit
	case ActionPush:
		return s.hintPush
	case ActionClean:
		return s.hintClean
	}
	return lipgloss.Style{}
}

package recap

import (
	"fmt"
	"strings"
)

// Heatmap intensity glyphs, low to high. Five tiers match the 5-tier ramp
// called out in the visual-language section of the plan.
var heatmapGlyphs = []rune{' ', '░', '▒', '▓', '█'}

// renderHeatmapStrip turns a slice of bucketed counts into a single-line
// heatmap. Intensity is scaled to maxIntensity; buckets with zero activity
// render as a blank (space) glyph, preserving the strip's width.
//
// Empty input returns "". maxIntensity <= 0 is treated as "no scale yet" and
// the strip renders all zeros. Buckets exceeding maxIntensity are clamped to
// the top tier rather than panicking.
func renderHeatmapStrip(bucketed []int, maxIntensity int, styles recapStyles) string {
	if len(bucketed) == 0 {
		return ""
	}
	var b strings.Builder
	for _, v := range bucketed {
		b.WriteRune(heatmapGlyphRune(v, maxIntensity))
	}
	return styles.accent.Render(b.String())
}

// heatmapGlyphRune maps a single bucket count to its ramp glyph.
// Linear bucketing across the ramp (5 tiers) keeps the code trivial; we can
// swap for quantile bucketing later if real data proves uneven.
func heatmapGlyphRune(v, maxIntensity int) rune {
	if v <= 0 || maxIntensity <= 0 {
		return heatmapGlyphs[0]
	}
	tier := (v * (len(heatmapGlyphs) - 1)) / maxIntensity
	if tier >= len(heatmapGlyphs) {
		tier = len(heatmapGlyphs) - 1
	}
	if tier < 1 {
		tier = 1 // any non-zero v gets at least the lowest visible tier
	}
	return heatmapGlyphs[tier]
}

// renderGradientBar draws a horizontal bar `▰▰▰▰▱▱▱▱  45%` where the filled
// portion is proportional to value/max. width is the total cell count of the
// bar (default ~10 reads well in a panel). Returns "" when max <= 0.
//
// The bar is followed by two spaces and the percentage rounded to whole
// numbers — callers can trim the suffix when they render their own label.
func renderGradientBar(value, maxVal, width int, styles recapStyles) string {
	if maxVal <= 0 || width <= 0 {
		return ""
	}
	if value < 0 {
		value = 0
	}
	if value > maxVal {
		value = maxVal
	}
	filled := (value * width) / maxVal
	if value > 0 && filled == 0 {
		filled = 1 // any non-zero value shows at least one block
	}
	pct := (value * 100) / maxVal
	bar := strings.Repeat("▰", filled) + strings.Repeat("▱", width-filled)
	return fmt.Sprintf("%s  %d%%", styles.accent.Render(bar), pct)
}

// renderIntraDayStrip draws a 24-cell strip (one per hour) showing event
// intensity across a day, with hour labels below. Used on the Day tab's
// Activity panel. Events is indexed by hour 0–23.
//
// Return is a two-line string: the strip on line 1, hour labels on line 2.
// Labels fall on hours 0, 3, 6, 9, 12, 15, 18, 21 — 8 anchors, each
// offset 3 cells — which matches the mockup in the plan.
func renderIntraDayStrip(events [24]int, styles recapStyles) string {
	maxV := 0
	for _, v := range events {
		if v > maxV {
			maxV = v
		}
	}
	// Row 1: the strip itself.
	var row strings.Builder
	for _, v := range events {
		row.WriteRune(heatmapGlyphRune(v, maxV))
	}

	// Row 2: hour labels at the 8 anchor hours, padded to line up with each
	// 3-hour tick on the strip above.
	var labels strings.Builder
	for h := 0; h < 24; h++ {
		if h%3 == 0 {
			labels.WriteString(fmt.Sprintf("%02d", h))
			// Already wrote 2 chars; skip the next cell-position because a
			// 2-char label occupies two strip cells.
			h++
		} else {
			labels.WriteRune(' ')
		}
	}
	return styles.accent.Render(row.String()) + "\n" + styles.muted.Render(labels.String())
}

package recap

import (
	"github.com/charmbracelet/lipgloss"
)

// renderPanel wraps body in a bordered block titled at the top-left corner.
// Width is the outer width of the panel (including borders). When useColor
// is false in styles, the border renders as plain ASCII characters instead
// of Unicode corners so piped output stays readable.
//
// Body is passed through verbatim — it may contain ANSI-styled text, blank
// lines, or internal spacing; we don't second-guess its content. Callers
// responsible for fitting body to `width - 4` (2 border + 2 padding).
func renderPanel(title, body string, width int, styles recapStyles) string {
	if width < 10 {
		width = 10 // don't draw a panel narrower than its minimal title chrome
	}
	border := lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color(colorBorder)).
		Padding(0, 2).
		Width(width - 2) // subtract border chars; lipgloss handles the rest
	if title == "" {
		return border.Render(body)
	}
	titled := styles.title.Render(title) + "\n\n" + body
	return border.Render(titled)
}

