	for _, h := range cases {
		out := s.styleForHint(h).Render("x")
		if !strings.Contains(out, "x") {
			t.Errorf("hint %q dropped text: %q", h, out)
		}
		if !strings.ContainsRune(out, '\x1b') {
			t.Errorf("hint %q produced no ANSI: %q", h, out)
		}
	}
}

