		return m.styles.muted.Render(label)
	}
	sep := m.styles.help.Render(" · ")

	rangeLabels := []struct {
		label string
		r     RangeKey
	}{
		{"day", RangeDay},
		{"week", RangeWeek},
		{"month", RangeMonth},
		{"30d", Range30d},
		{"90d", Range90d},
	}
	parts := make([]string, 0, len(rangeLabels))
	for _, rl := range rangeLabels {
		parts = append(parts, tab(rl.label, m.view.Range == rl.r))
	}
	rangeBar := strings.Join(parts, sep)

	agentVal := "all"
	if m.agentFilter != "" {
		agentVal = m.agentFilter
	}
	agent := m.styles.muted.Render("agent: ") + m.styles.accent.Render("["+agentVal+"]")

	viewVal := string(m.mode)
	if viewVal == "" {
		viewVal = string(ViewBoth)
	}
	view := m.styles.muted.Render("view: ") + m.styles.accent.Render("["+viewVal+"]")

	return "  " + rangeBar + "     " + agent + "     " + view
}

