// renderAgentsView draws the Agents view: one AgentCard panel per agent.
// When mode is "me" only, the contributors column is suppressed; "contributors"
// hides the me column; "both" shows side-by-side.
//
// When the user requested "both" but no card carries contributor data
// (common for --day ranges, solo repos, unauthed users, untracked repos),
// we auto-collapse to "me" so users don't see a column full of em-dashes.
// Explicit --view contributors still renders even when empty so users can
// see "this is where team data lands."
func renderAgentsView(cards []AgentCard, mode ViewMode, styles Styles) string {
	if len(cards) == 0 {
		return styles.muted.Render("(no agents in range)")
	}
	effectiveMode := mode
	if mode == ViewBoth && !hasContribData(cards) {
		effectiveMode = ViewMe
	}
	var blocks []string
	for _, c := range cards {
		blocks = append(blocks, renderAgentCard(c, effectiveMode, styles))
	}
	return strings.Join(blocks, "\n\n")
}

// hasContribData returns true when any card has a non-zero contributor
// signal (sessions, tokens, or distinct contributors). Zero across all cards
// means the server call returned nothing useful for this view.
func hasContribData(cards []AgentCard) bool {
	for _, c := range cards {
		if c.ContribSessions > 0 || c.ContribTokens > 0 || c.ContribCount > 0 {
			return true
		}
	}
	return false
}

func (m TUIModel) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // mirrors Update's bubbletea contract
	key := msg.String()
	switch key {
	case "q", "ctrl+c", "esc":
		return m, tea.Quit

	// Range nav: left/right arrows cycle through the 5 ranges. Tab / Shift-Tab
	// do the same (standard dashboard tab affordance). Number shortcuts still
	// work for power users, and d/w/m are the one-letter range hotkeys.
	case "right", "l", "tab":
		m.view = rebuildView(m.sessions, nextRange(m.view.Range), m.agentFilter, m.mode)
		refreshViewport(&m)
	case "left", "h", "shift+tab":
		m.view = rebuildView(m.sessions, prevRange(m.view.Range), m.agentFilter, m.mode)
		refreshViewport(&m)
	case "1", "d":
		m.view = rebuildView(m.sessions, RangeDay, m.agentFilter, m.mode)
		refreshViewport(&m)
	case "2", "w":
		m.view = rebuildView(m.sessions, RangeWeek, m.agentFilter, m.mode)
		refreshViewport(&m)
	case "3", "M":
		m.view = rebuildView(m.sessions, RangeMonth, m.agentFilter, m.mode)
		refreshViewport(&m)
	case "4":
		m.view = rebuildView(m.sessions, Range30d, m.agentFilter, m.mode)
		refreshViewport(&m)
	case "5":
		m.view = rebuildView(m.sessions, Range90d, m.agentFilter, m.mode)
		refreshViewport(&m)

	// Filter toggles: single-key cycle for agent + view mode.
	case "a":
		m.agentFilter = cycleAgent(m.agents, m.agentFilter)
		m.view = rebuildView(m.sessions, m.view.Range, m.agentFilter, m.mode)
		refreshViewport(&m)
	case "v":
		m.mode = cycleMode(m.mode)
		m.view = rebuildView(m.sessions, m.view.Range, m.agentFilter, m.mode)
		refreshViewport(&m)

	// Vertical scroll. Up/down for single line; space / pgup / pgdn for
	// half-page; home/end for jumps. Mouse wheel handled in Update.
	case "up", "k":
		m.viewport.ScrollUp(1)
	case "down", "j":
		m.viewport.ScrollDown(1)
	case "pgup", "b":
		m.viewport.HalfPageUp()
	case "pgdown", " ", "pgdn":
		m.viewport.HalfPageDown()
	case "home", "g":
		m.viewport.GotoTop()
	case "end", "G":
		m.viewport.GotoBottom()
	}
	return m, nil
}

// rangeOrder is the navigation sequence used by left/right arrow + tab.
// Stable order means the visual header's tab positions and keyboard
// traversal order always agree.
var rangeOrder = []RangeKey{RangeDay, RangeWeek, RangeMonth, Range30d, Range90d}

func nextRange(current RangeKey) RangeKey {
	for i, r := range rangeOrder {
		if r == current {
			return rangeOrder[(i+1)%len(rangeOrder)]
		}
	}
	return rangeOrder[0]
}

func prevRange(current RangeKey) RangeKey {
	for i, r := range rangeOrder {
		if r == current {
			return rangeOrder[(i-1+len(rangeOrder))%len(rangeOrder)]
		}
	}
	return rangeOrder[0]
}

// View is everything a renderer needs. Pure data — no styling, no I/O.
// The Footer string is left to the renderer; the view exposes the raw bits.
type View struct {
	Title      string
	Range      RangeKey
	Mode       ViewMode // rendering path dispatches on this
