		return styles.label.Render(header) + "\n" + renderIntraDayStrip(events, styles)
	}
	strip := renderHeatmapStrip(view.Activity, maxOf(view.Activity), styles)
	labels := renderRangeAxisLabels(view.Range, len(view.Activity), styles)
	return styles.label.Render(header) + "\n" + strip + "\n" + labels
}

// renderRangeAxisLabels draws a second row of labels under the heatmap
// strip so multi-day ranges have context for each cell.
//   - week: M T W T F S S (one letter per day, aligned with cells)
//   - month/30d/90d: date markers every ~7 cells, formatted "Apr 1"
//
// All labels are styled with the muted grey so the heatmap row stays
// visually prominent.
func renderRangeAxisLabels(r RangeKey, cellCount int, styles Styles) string {
	now := time.Now()
	switch r {
	case RangeWeek:
		// 7 day-of-week initials, starting 7 days ago.
		start := now.AddDate(0, 0, -6)
		var out []rune
		for i := 0; i < 7 && i < cellCount; i++ {
			d := start.AddDate(0, 0, i)
			initials := []rune{'M', 'T', 'W', 'T', 'F', 'S', 'S'}
			// Go's Weekday enum is Sun=0..Sat=6; map to our index where M=0.
			idx := (int(d.Weekday()) + 6) % 7
			out = append(out, initials[idx])
		}
		return styles.muted.Render(string(out))
	case RangeMonth, Range30d, Range90d:
		// Date markers every 7 cells. Each marker occupies up to 6 characters;
		// pad between markers so the next one lines up with its cell.
		step := 7
		if r == Range90d {
			step = 14
		}
		start := now.AddDate(0, 0, -(cellCount - 1))
		var out strings.Builder
		written := 0
		for i := 0; i < cellCount; i += step {
			if i > written {
				out.WriteString(strings.Repeat(" ", i-written))
				written = i
			}
			label := start.AddDate(0, 0, i).Format("Jan 2")
			out.WriteString(label)
			written += len(label)
		}
		return styles.muted.Render(out.String())
	}
	return ""
}

