const cardValueWidth = 14

// padValue renders a styled value padded to cardValueWidth. Uses a plain
// left-pad since our values are ASCII-safe (digits + token suffixes).
func padValue(s string, style lipgloss.Style) string {
	if len(s) < cardValueWidth {
		s += strings.Repeat(" ", cardValueWidth-len(s))
	}
	return style.Render(s)
}

// centerLabel centers a short label inside cardValueWidth so the "me" /
// "contributors" headers sit visually above their metric columns. When
// the label is wider than the column, it's returned as-is (no truncation).
func centerLabel(s string) string {
	if len(s) >= cardValueWidth {
		return s
	}
	total := cardValueWidth - len(s)
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

