const (
	cardLabelWidth = 24
	cardValueWidth = 14
)

// padAndStyle pads plain text on the right to width, then applies style.
// Bypasses fmt's width accounting which silently breaks when style adds
// ANSI escape bytes. Used for both the leftmost label column and each
// metric value column so rows and headers line up on visible columns.
func padAndStyle(s string, width int, style lipgloss.Style) string {
	if len(s) < width {
		s += strings.Repeat(" ", width-len(s))
	}
	return style.Render(s)
}

// padValue is a thin wrapper kept for call-site readability.
func padValue(s string, style lipgloss.Style) string {
	return padAndStyle(s, cardValueWidth, style)
}

// padLabel pads a row label (Sessions, Checkpoints, etc.) to the label
// column width before styling so the value column starts on the exact
// same visible column as the "me" / "contributors" header above.
func padLabel(s string, style lipgloss.Style) string {
	return padAndStyle(s, cardLabelWidth, style)
}

// plainPadLeft pads plain (unstyled) text to width. Useful for the header
// row where the leftmost column is empty but still needs to occupy its
// cell before the styled value header starts.
func plainPadLeft(s string, width int) string {
	if len(s) < width {
		s += strings.Repeat(" ", width-len(s))
	}
	return s
}

