// buildAgentCards turns a list of filtered sessions into per-agent cards for
// the "me" side. Contributor fields are left zero — the server-overview
// integration fills them in later.
func buildAgentCards(sessions []RecapSession) []AgentCard {
	type bucket struct {
		card        *AgentCard
		labelCounts map[string]int
		models      map[string]int
		repos       map[string]int
	}
	buckets := map[string]*bucket{}
	for _, s := range sessions {
		for _, agent := range s.AgentsUsed {
			b, ok := buckets[agent]
			if !ok {
				b = &bucket{
					card:        &AgentCard{Agent: agent},
					labelCounts: map[string]int{},
					models:      map[string]int{},
					repos:       map[string]int{},
				}
				buckets[agent] = b
			}
			b.card.MeSessions++
			// Sessions carry the authoritative token totals (populated from
			// session.State, which reflects metadata.json). Attributing once
			// per (session, agent) avoids double-counting even if AgentsUsed
			// ever grows past a single entry.
			if s.TokenUsage != nil {
				b.card.MeTokens += s.TokenUsage.InputTokens + s.TokenUsage.OutputTokens
			}
			for _, cp := range s.Checkpoints {
				b.card.MeCheckpoints++
				for _, lbl := range cp.Labels {
					b.labelCounts[lbl]++
				}
			}
			for _, m := range s.ModelsUsed {
				b.models[m]++
			}
			if s.Repo != "" {
				b.repos[s.Repo]++
			}
		}
