// joinOrDash returns "" when items is empty (caller renders the "—"); else
// joins top-3 items as a comma-separated string rendered with the given style.
func joinOrDash(items []string, style lipgloss.Style) string {
	if len(items) == 0 {
		return ""
	}
	if len(items) > 3 {
		items = items[:3]
	}
	return style.Render(strings.Join(items, ", "))
}

// toolMixFromLabels is a placeholder when we don't have per-agent toolMix on
// the me side. Today the CLI's "me" doesn't carry toolMix (that data lives in
// per-cp analysis under MeToolMix which isn't populated until we switch the
// me-side enrichment to batch). Returns nil so the renderer shows "—".
func toolMixFromLabels(_ []LabelCount) map[string]int { return nil }

// formatToolMixInline renders a toolMix map as "shell 60% · fileOps 25% · …"
// with the biggest categories first. Empty input returns "".
func formatToolMixInline(mix map[string]int, styles Styles) string {
	if len(mix) == 0 {
		return ""
	}
	total := 0
	for _, c := range mix {
		total += c
	}
	if total == 0 {
		return ""
	}
	type kv struct {
		k string
		v int
	}
	all := make([]kv, 0, len(mix))
	for k, v := range mix {
		if v > 0 {
			all = append(all, kv{k, v})
		}
	}
	sort.Slice(all, func(i, j int) bool {
		if all[i].v != all[j].v {
			return all[i].v > all[j].v
		}
		return all[i].k < all[j].k
	})
	n := len(all)
	if n > 3 {
		n = 3
	}
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		pct := (all[i].v * 100) / total
		parts = append(parts, fmt.Sprintf("%s %d%%", styles.accent.Render(all[i].k), pct))
	}
	return strings.Join(parts, " · ")
}

