// Per-agent aggregator for /api/v1/me/recap.
//
// The recap endpoint returns two columns of agent-scoped metrics:
//   me           — aggregates across the authenticated user's checkpoints
//   contributors — aggregates across every contributor's checkpoints on the repo
//
// Both columns share the same aggregation shape (labels / skills / MCP /
// toolMix counts, plus tokens + checkpoint count where applicable). The CLI
// consumes this endpoint so it doesn't have to round-trip dozens of per-cp
// analysis requests and the batch endpoint + reconstruct agent attribution.

import type { StoredCheckpointAnalysis, ToolProfile } from "../types"

/**
 * Shape of an analysis row with its producing agent attached. Callers
 * join analyses with checkpoint/commit records before handing them here.
 */
export interface AnalysisWithAgent {
  checkpointId: string
  agent: string
  analysis: StoredCheckpointAnalysis | null
}

/**
 * LabelCount / SkillCount / McpCount follow the same sorted-desc shape the
 * frontend already renders elsewhere.
 */
export interface LabelCount {
  label: string
  count: number
}

export interface SkillCount {
  skill: string
  count: number
}

export interface McpCount {
  name: string
  count: number
}

/**
 * AgentAggregate is the shared shape for either the me side or the
 * contributors side of a recap row. tokens / checkpoints may be 0 when
 * the caller doesn't supply a source (e.g. contributor tokens come from a
 * separate SQL aggregate via /agent-activity).
 */
export interface AgentAggregate {
  checkpoints: number
  tokens: number
  labels: LabelCount[]
  skills: SkillCount[]
  mcpServers: McpCount[]
  toolMix: ToolMix
}

/**
 * ToolMix mirrors ToolProfile.categories but hoisted to the top level so
 * the response is easier to consume (no nested `categories` wrapper).
 */
export interface ToolMix {
  shell: number
  fileOps: number
  search: number
  mcp: number
  agent: number
  other: number
}

const emptyToolMix = (): ToolMix => ({
  shell: 0,
  fileOps: 0,
  search: 0,
  mcp: 0,
  agent: 0,
  other: 0,
})

/**
 * aggregateByAgent groups per-checkpoint analyses by agent and rolls up
 * labels, skills, MCP servers, and tool-profile counts. Inputs with null
 * analysis (pending / not_available / failed) contribute a checkpoint
 * count but no qualitative fields.
 *
 * `tokensByAgent` is optional supplemental input — when provided, its
 * values override the default (0) for `tokens`. This lets the handler
 * pull tokens from `agent-activity` (SQL aggregate) rather than summing
 * across analysis rows, which is what the dashboard already does.
 */
export function aggregateByAgent(
  rows: AnalysisWithAgent[],
  tokensByAgent?: Record<string, number>,
): Record<string, AgentAggregate> {
  const out: Record<string, AgentAggregate> = {}

  for (const row of rows) {
    const key = row.agent
    if (!key) continue
    let agg = out[key]
    if (!agg) {
      agg = {
        checkpoints: 0,
        tokens: tokensByAgent?.[key] ?? 0,
        labels: [],
        skills: [],
        mcpServers: [],
        toolMix: emptyToolMix(),
      }
      out[key] = agg
    }
    agg.checkpoints += 1

    const analysis = row.analysis
    if (!analysis) continue

    const labelCounts = new Map<string, number>()
    for (const l of analysis.extraction?.labels ?? []) {
      labelCounts.set(l, (labelCounts.get(l) ?? 0) + 1)
    }
    // Merge into existing agg.labels
    for (const [label, count] of labelCounts) {
      const existing = agg.labels.find((x) => x.label === label)
      if (existing) existing.count += count
      else agg.labels.push({ label, count })
    }

    for (const skill of analysis.skillsUsed ?? []) {
      const existing = agg.skills.find((x) => x.skill === skill)
      if (existing) existing.count += 1
      else agg.skills.push({ skill, count: 1 })
    }

    for (const m of analysis.mcpServersUsed ?? []) {
      const existing = agg.mcpServers.find((x) => x.name === m.name)
      if (existing) existing.count += m.count
      else agg.mcpServers.push({ name: m.name, count: m.count })
    }

    if (analysis.toolProfile) {
      accumulateToolMix(agg.toolMix, analysis.toolProfile)
    }
  }

  // Sort each per-agent list desc by count, stable by name tiebreaker so
  // consumers get deterministic display order.
  for (const agg of Object.values(out)) {
    agg.labels.sort(byCountThenName((x) => x.label))
    agg.skills.sort(byCountThenName((x) => x.skill))
    agg.mcpServers.sort(byCountThenName((x) => x.name))
  }

  return out
}

function accumulateToolMix(dest: ToolMix, tp: ToolProfile): void {
  const cats = tp.categories
  dest.shell += cats.shell?.count ?? 0
  dest.fileOps += cats.fileOps?.count ?? 0
  dest.search += cats.search?.count ?? 0
  dest.mcp += cats.mcp?.count ?? 0
  dest.agent += cats.agent?.count ?? 0
  dest.other += cats.other?.count ?? 0
}

function byCountThenName<T extends { count: number }>(nameOf: (x: T) => string) {
  return (a: T, b: T) => {
    if (a.count !== b.count) return b.count - a.count
    return nameOf(a).localeCompare(nameOf(b))
  }
}

// GET /api/v1/me/recap — per-agent recap aggregates for the CLI.
//
// Returns, for every agent the user has used in the window (and optionally
// every agent any contributor used on a scoped repo):
//   - me side: checkpoints + labels + skills + mcpServers + toolMix
//     (tokens intentionally omitted — the CLI sums metadata.json locally)
//   - contributors side: the same shape aggregated across all contributors
//     to the specified repo (requires ?repo=org/name)
//
// This endpoint consolidates three CLI operations into one request:
//   1. GET /api/v1/me/checkpoints       → list my checkpoints
//   2. POST /checkpoints/analyses/batch → analyses for each cp
//   3. GET /:org/:repo/overview/*       → contributor aggregates
//
// Without this endpoint the CLI has to do all three itself and attribute
// analyses to agents via the commits endpoint — a lot of round trips and
// brittle client-side joining. Centralizing on the server matches the
// pattern established by /me/activity (PR #1590).

import { Hono } from "hono"
import { describeRoute, resolver } from "hono-openapi"
import { z } from "zod"

import type { Env, Variables } from "../env"
import { getDb } from "../lib/db"
import { requireBearerAuth } from "../lib/middleware"
import {
  aggregateByAgent,
  type AgentAggregate,
  type AnalysisWithAgent,
} from "../lib/recap-aggregator"
import { recordSpanError } from "../lib/telemetry"
import { parseTimeframeParams } from "./cache"

const recapRoutes = new Hono<{ Bindings: Env; Variables: Variables }>()

recapRoutes.use("*", requireBearerAuth)

const errorSchema = z.object({ error: z.string() })

const labelCountSchema = z.object({ label: z.string(), count: z.number() })
const skillCountSchema = z.object({ skill: z.string(), count: z.number() })
const mcpCountSchema = z.object({ name: z.string(), count: z.number() })
const toolMixSchema = z.object({
  shell: z.number(),
  fileOps: z.number(),
  search: z.number(),
  mcp: z.number(),
  agent: z.number(),
  other: z.number(),
})

const agentAggregateSchema = z.object({
  checkpoints: z.number(),
  tokens: z.number(),
  labels: z.array(labelCountSchema),
  skills: z.array(skillCountSchema),
  mcpServers: z.array(mcpCountSchema),
  toolMix: toolMixSchema,
})

const perAgentEntrySchema = z.object({
  me: agentAggregateSchema,
  contributors: agentAggregateSchema.nullable(),
})

const recapResponseSchema = z.object({
  timeframe: z.string(),
  repo: z.string().nullable(),
  agents: z.record(z.string(), perAgentEntrySchema),
  contributors: z
    .object({
      distinctUsers: z.number(),
      totalTokens: z.number(),
      totalCheckpoints: z.number(),
    })
    .nullable(),
  updated_at: z.string(),
})

recapRoutes.get(
  "/",
  describeRoute({
    tags: ["Me"],
    summary: "Per-agent recap aggregates for the authenticated user",
    description:
      "Returns per-agent aggregates (checkpoints, labels, skills, MCP servers, " +
      "tool-profile mix) for the authenticated user's activity in the requested " +
      "window. When ?repo=org/name is supplied, each agent row also carries a " +
      "`contributors` counterpart aggregated across every contributor on the " +
      "repo — what powers the 'you vs. team' columns in `entire recap`.",
    parameters: [
      {
        name: "timeframe",
        in: "query",
        required: false,
        description: "Window of activity to aggregate. Defaults to last-6-months.",
        schema: {
          type: "string",
          enum: ["last-month", "last-3-months", "last-6-months"],
        },
      },
      {
        name: "repo",
        in: "query",
        required: false,
        description:
          "Restrict me-side aggregates and enable the contributors side. " +
          "Format: 'org/name'. Without it, me-side aggregates span every repo " +
          "the user has checkpoints on and the contributors side is null.",
        schema: { type: "string" },
      },
      {
        name: "limit",
        in: "query",
        required: false,
        description: "Max checkpoints to consider (1-1000, default 500).",
        schema: { type: "integer", minimum: 1, maximum: 1000, default: 500 },
      },
    ],
    responses: {
      200: {
        description: "Per-agent recap aggregates",
        content: { "application/json": { schema: resolver(recapResponseSchema) } },
      },
      401: {
        description: "Not authenticated",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      404: {
        description: "User or repo not found",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      500: {
        description: "Failed to build recap",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    const userId = c.get("userId") as string
    const { limit, startDate, endDate } = parseTimeframeParams(c)
    const repoParam = c.req.query("repo")?.trim() || null

    try {
      const db = getDb(c.env)
      const user = await db.users.getWithCache(c.env.ENTIRE_CACHE, userId)
      if (!user) return c.json({ error: "User not found" }, 404)

      // --- me side ---
      // Pull the user's checkpoints in the window. When a repo is scoped,
      // filter here so we don't drag other repos into the me aggregates.
      const myCheckpoints = await db.checkpoints.getByUser(
        userId,
        user.github_id,
        startDate.toISOString(),
        endDate.toISOString(),
        limit,
      )
      const scopedMyCheckpoints = repoParam
        ? myCheckpoints.filter((cp) => cp.repo_full_name === repoParam)
        : myCheckpoints

      const meRows = await buildAnalysisRows(db, scopedMyCheckpoints, c.env)
      const meByAgent = aggregateByAgent(meRows)

      // --- contributors side ---
      // Only available when a specific repo is requested; otherwise the
      // "contributors" concept doesn't have a well-defined scope.
      let contribByAgent: Record<string, AgentAggregate> = {}
      let contribSummary: {
        distinctUsers: number
        totalTokens: number
        totalCheckpoints: number
      } | null = null

      if (repoParam) {
        const repoParts = repoParam.split("/")
        if (repoParts.length === 2 && repoParts[0] && repoParts[1]) {
          const repo = await db.repos.getByFullName(repoParam)
          if (repo) {
            const branch = repo.default_branch ?? "main"
            const { daily: agentActivity } = await getAgentActivityBundle(
              db,
              repo.id,
              branch,
              startDate.toISOString(),
              endDate.toISOString(),
            )

            // Sum tokens per agent from agent-activity — SQL aggregate that
            // doesn't require loading every analysis.
            const tokensByAgent: Record<string, number> = {}
            for (const row of agentActivity) {
              tokensByAgent[row.agent] = (tokensByAgent[row.agent] ?? 0) + (row.tokens ?? 0)
            }

            const allCheckpoints = await db.checkpoints.getForBranch(repo.id, branch, {
              limit,
            })
            const windowed = allCheckpoints.filter((cp) => {
              if (!cp.commit_date) return false
              const t = new Date(cp.commit_date).getTime()
              return t >= startDate.getTime() && t < endDate.getTime()
            })

            const contribRows = await buildAnalysisRows(db, windowed, c.env, repo.id)
            contribByAgent = aggregateByAgent(contribRows, tokensByAgent)

            const contributorsResult = await db.repoOverview.getContributorAgents(
              repo.id,
              branch,
              startDate.toISOString(),
              endDate.toISOString(),
            )
            contribSummary = {
              distinctUsers: contributorsResult.contributors.length,
              totalTokens: Object.values(tokensByAgent).reduce((s, n) => s + n, 0),
              totalCheckpoints: windowed.length,
            }
          }
        }
      }

      // Merge me + contributors into the per-agent map, keyed by agent.
      const allAgents = new Set<string>([
        ...Object.keys(meByAgent),
        ...Object.keys(contribByAgent),
      ])
      const agents: Record<string, { me: AgentAggregate; contributors: AgentAggregate | null }> = {}
      for (const name of allAgents) {
        agents[name] = {
          me: meByAgent[name] ?? emptyAggregate(),
          contributors: contribByAgent[name] ?? null,
        }
      }

      return c.json({
        timeframe: c.req.query("timeframe") ?? "last-6-months",
        repo: repoParam,
        agents,
        contributors: contribSummary,
        updated_at: new Date().toISOString(),
      })
    } catch (err) {
      console.error("Failed to build recap:", err)
      recordSpanError(err)
      return c.json({ error: "Failed to build recap" }, 500)
    }
  },
)

function emptyAggregate(): AgentAggregate {
  return {
    checkpoints: 0,
    tokens: 0,
    labels: [],
    skills: [],
    mcpServers: [],
    toolMix: { shell: 0, fileOps: 0, search: 0, mcp: 0, agent: 0, other: 0 },
  }
}

/**
 * buildAnalysisRows loads analyses for the given checkpoints and attaches
 * each to its producing agent. When repoId is passed explicitly (contrib
 * path), analyses are keyed by that repo; for the me path we fall back to
 * looking up the repo per checkpoint via cp.repo_id.
 */
async function buildAnalysisRows(
  db: ReturnType<typeof getDb>,
  checkpoints: Array<{
    checkpoint_id: string
    agent: string | null
    repo_id?: string | null
  }>,
  _env: Env,
  repoId?: string,
): Promise<AnalysisWithAgent[]> {
  const byRepo = new Map<string, string[]>()
  for (const cp of checkpoints) {
    const rid = repoId ?? cp.repo_id ?? ""
    if (!rid || !cp.checkpoint_id) continue
    const arr = byRepo.get(rid) ?? []
    arr.push(cp.checkpoint_id)
    byRepo.set(rid, arr)
  }

  const analysesById = new Map<string, ReturnType<typeof parseAnalysisRow>>()
  for (const [rid, ids] of byRepo) {
    const rows = await db.analyses.getByCheckpointIds(rid, ids)
    for (const row of rows) {
      analysesById.set(row.checkpoint_id, parseAnalysisRow(row))
    }
  }

  const out: AnalysisWithAgent[] = []
  for (const cp of checkpoints) {
    if (!cp.checkpoint_id) continue
    out.push({
      checkpointId: cp.checkpoint_id,
      agent: cp.agent ?? "unknown",
      analysis: analysesById.get(cp.checkpoint_id) ?? null,
    })
  }
  return out
}

/**
 * parseAnalysisRow mirrors formatCheckpointAnalysisResponse from cache.ts
 * but returns the parsed analysis JSON directly (or null for non-complete
 * states) without the status discriminator.
 */
function parseAnalysisRow(row: {
  status: string
  analysis_json: string | null
}): import("../types").StoredCheckpointAnalysis | null {
  if (row.status !== "complete" || !row.analysis_json) return null
  try {
    return JSON.parse(row.analysis_json)
  } catch {
    return null
  }
}

/**
 * getAgentActivityBundle wraps repoOverview.getAgentActivityDaily and
 * returns both the raw rows and the computed-per-agent tokens map. Splits
 * into its own helper so the handler stays readable.
 */
async function getAgentActivityBundle(
  db: ReturnType<typeof getDb>,
  repoId: string,
  branch: string,
  since?: string,
  until?: string,
): Promise<{
  daily: Awaited<ReturnType<typeof db.repoOverview.getAgentActivityDaily>>
}> {
  const daily = await db.repoOverview.getAgentActivityDaily(repoId, branch, since, until)
  return { daily }
}

export { recapRoutes }

