// Timeframe parsing — same semantics as /me/activity and /me/commits.
// Inlined here so the recap route doesn't depend on PR #1590's shared
// helper before that lands. Swap the import once it exists.
type TimeframeKey = "last-month" | "last-3-months" | "last-6-months"
const defaultTimeframe: TimeframeKey = "last-6-months"
const timeframeMonths: Record<TimeframeKey, number> = {
  "last-month": 1,
  "last-3-months": 3,
  "last-6-months": 6,
}

function parseTimeframeParams(c: {
  req: { query: (name: string) => string | undefined }
}): { limit: number; startDate: Date; endDate: Date } {
  const rawTf = c.req.query("timeframe") ?? defaultTimeframe
  const tf: TimeframeKey = rawTf in timeframeMonths ? (rawTf as TimeframeKey) : defaultTimeframe
  const rawLimit = parseInt(c.req.query("limit") ?? "500", 10)
  const limit = Number.isFinite(rawLimit) ? Math.min(Math.max(rawLimit, 1), 1000) : 500
  const endDate = new Date()
  const startDate = new Date(endDate)
  startDate.setMonth(startDate.getMonth() - timeframeMonths[tf])
  return { limit, startDate, endDate }
}

