    },
  }),
}))

import { meRoutes } from "./me"

const mockEnv = { ENTIRE_CACHE: {} } as unknown as Env
const mockExecutionCtx = { waitUntil: vi.fn(), passThroughOnException: vi.fn() }

function get(path: string) {
  return meRoutes.request(path, { headers: {} }, { ...mockEnv, ...mockExecutionCtx })
}

function mkUser() {
  return { id: "user-1", github_id: 42 }
}

function mkCheckpoint(overrides: Record<string, unknown> = {}) {
  return {
    checkpoint_id: "cp-1",
    agent: "claude-code",
    repo_id: "repo-1",
    repo_full_name: "entireio/cli",
    commit_date: new Date().toISOString(),
    input_tokens: 1000,
    output_tokens: 500,
    ...overrides,
  }
}

function mkAnalysisRow(checkpointId: string, overrides: Record<string, unknown> = {}) {
  const analysis = {
    pipeline_version: "test",
    totalFilesChanged: 3,
    total_transcript_tokens: 12345,
    extraction: { labels: ["bug_fix"] },
    skillsUsed: ["superpowers", "brainstorming"],
    mcpServersUsed: [{ name: "linear", count: 2 }],
    toolProfile: {
      total: 10,
      categories: {
        shell: { count: 6 },
        fileOps: { count: 3 },
        search: { count: 1 },
        mcp: { count: 0 },
        agent: { count: 0 },
        other: { count: 0 },
      },
    },
    agentsUsed: ["claude-code"],
    modelsUsed: ["opus-4-7"],
    ...overrides,
  }
  return {
    checkpoint_id: checkpointId,
    status: "complete",
    analysis_json: JSON.stringify(analysis),
  }
}

beforeEach(() => {
  vi.clearAllMocks()
})

describe("GET /me/recap", () => {
  it("returns per-agent me aggregates with skills/mcp/toolMix/transcript_tokens/files", async () => {
    mockGetWithCache.mockResolvedValue(mkUser())
    mockGetByUser.mockResolvedValue([mkCheckpoint({ checkpoint_id: "cp-a" })])
    mockGetByCheckpointIds.mockResolvedValue([mkAnalysisRow("cp-a")])

    const res = await get("/recap?timeframe=last-month")
    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>

    const agents = body.agents as Record<string, { me: Record<string, unknown> }>
    const me = agents["claude-code"].me

    expect(me.checkpoints).toBe(1)
    expect(me.transcriptTokens).toBe(12345)
    expect(me.filesChanged).toBe(3)
    expect(me.skills).toEqual([
      { skill: "brainstorming", count: 1 },
      { skill: "superpowers", count: 1 },
    ])
    expect(me.mcpServers).toEqual([{ name: "linear", count: 2 }])
    expect(me.toolMix).toMatchObject({ shell: 6, fileOps: 3, search: 1 })
    // Labels come from extraction — present when LLM ran.
    expect(me.labels).toEqual([{ label: "bug_fix", count: 1 }])
  })

  it("keeps skills/mcp/toolMix/tokens/files even when extraction (labels) is absent", async () => {
    // Simulate LLM-off scenario: analysis has deterministic fields but no extraction.
    const analysis = {
      pipeline_version: "test",
      totalFilesChanged: 2,
      total_transcript_tokens: 9000,
      // extraction intentionally omitted → should degrade to labels=[]
      skillsUsed: ["s1"],
      mcpServersUsed: [],
      toolProfile: {
        total: 4,
        categories: {
          shell: { count: 2 },
          fileOps: { count: 2 },
          search: { count: 0 },
          mcp: { count: 0 },
          agent: { count: 0 },
          other: { count: 0 },
        },
      },
      modelsUsed: ["m1"],
      agentsUsed: ["claude-code"],
    }
    mockGetWithCache.mockResolvedValue(mkUser())
    mockGetByUser.mockResolvedValue([mkCheckpoint({ checkpoint_id: "cp-b" })])
    mockGetByCheckpointIds.mockResolvedValue([
      { checkpoint_id: "cp-b", status: "complete", analysis_json: JSON.stringify(analysis) },
    ])

    const res = await get("/recap?timeframe=last-month")
    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>
    const me = (body.agents as Record<string, { me: Record<string, unknown> }>)["claude-code"].me

    expect(me.labels).toEqual([])
    expect(me.skills).toEqual([{ skill: "s1", count: 1 }])
    expect(me.transcriptTokens).toBe(9000)
    expect(me.filesChanged).toBe(2)
    expect(me.toolMix).toMatchObject({ shell: 2, fileOps: 2 })
  })

  it("scopes to a repo and includes contributors when ?repo= is set", async () => {
    mockGetWithCache.mockResolvedValue(mkUser())
    mockGetByUser.mockResolvedValue([
      mkCheckpoint({ checkpoint_id: "cp-a", repo_full_name: "entireio/cli" }),
