package recap

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

// RecapEndpointResponse mirrors the shape returned by
// GET /api/v1/me/recap on entire.io. Bearer-auth, repo-scoped (optional).
//
// Mirrors api/src/routes/recap.ts + api/src/lib/recap-aggregator.ts on the
// server. Keep these types in sync when either side changes.
type RecapEndpointResponse struct {
	Timeframe   string                     `json:"timeframe"`
	Repo        *string                    `json:"repo"`
	Agents      map[string]RecapAgentEntry `json:"agents"`
	Contributors *RecapContribSummary       `json:"contributors"`
	UpdatedAt   string                     `json:"updated_at"`
}

// RecapAgentEntry is one agent row with both me + contributors columns.
type RecapAgentEntry struct {
	Me           RecapAgentAggregate  `json:"me"`
	Contributors *RecapAgentAggregate `json:"contributors"`
}

// RecapAgentAggregate is the per-side per-agent payload. transcriptTokens
// and filesChanged are the deterministic "survives LLM-off" fields;
// labels require LLM analysis to be complete.
type RecapAgentAggregate struct {
	Checkpoints      int               `json:"checkpoints"`
	Tokens           int               `json:"tokens"`
	TranscriptTokens int               `json:"transcriptTokens"`
	FilesChanged     int               `json:"filesChanged"`
	Labels           []RecapLabelCount `json:"labels"`
	Skills           []RecapSkillCount `json:"skills"`
	MCPServers       []RecapMcpCount   `json:"mcpServers"`
	ToolMix          RecapToolMix      `json:"toolMix"`
}

type RecapLabelCount struct {
	Label string `json:"label"`
	Count int    `json:"count"`
}
type RecapSkillCount struct {
	Skill string `json:"skill"`
	Count int    `json:"count"`
}
type RecapMcpCount struct {
	Name  string `json:"name"`
	Count int    `json:"count"`
}
type RecapToolMix struct {
	Shell   int `json:"shell"`
	FileOps int `json:"fileOps"`
	Search  int `json:"search"`
	MCP     int `json:"mcp"`
	Agent   int `json:"agent"`
	Other   int `json:"other"`
}

// RecapContribSummary is the repo-wide rollup returned alongside per-agent
// data when ?repo= is set. Nil when no repo was specified.
type RecapContribSummary struct {
	DistinctUsers    int `json:"distinctUsers"`
	TotalTokens      int `json:"totalTokens"`
	TotalCheckpoints int `json:"totalCheckpoints"`
}

// FetchMeRecap calls GET /api/v1/me/recap?timeframe=&repo=&limit= and
// returns the decoded response. Any error (network, non-2xx, decode)
// surfaces to the caller; this is the "fast path" that replaces the old
// commits + batch-analyses + overview fetch stack once the server endpoint
// is deployed.
//
// timeframe is one of the values the server accepts ("last-month",
// "last-3-months", "last-6-months"). repo is "org/name" or empty.
func FetchMeRecap(
	ctx context.Context,
	client *api.Client,
	timeframe, repo string,
	limit int,
) (*RecapEndpointResponse, error) {
	if client == nil {
		return nil, fmt.Errorf("me/recap: nil client")
	}
	q := url.Values{}
	if timeframe != "" {
		q.Set("timeframe", timeframe)
	}
	if repo != "" {
		q.Set("repo", repo)
	}
	if limit > 0 {
		q.Set("limit", fmt.Sprintf("%d", limit))
	}
	path := "/api/v1/me/recap"
	if encoded := q.Encode(); encoded != "" {
		path += "?" + encoded
	}
	resp, err := client.Get(ctx, path)
	if err != nil {
		return nil, fmt.Errorf("me/recap get: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode >= 400 {
		body, _ := io.ReadAll(resp.Body) //nolint:errcheck // best-effort error body
		return nil, fmt.Errorf("me/recap: http %d: %s", resp.StatusCode, string(body))
	}
	var out RecapEndpointResponse
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return nil, fmt.Errorf("me/recap decode: %w", err)
	}
	return &out, nil
}

// timeframeForRange maps our RangeKey to the timeframe value the server
// endpoint accepts. The server only supports last-month / last-3-months /
// last-6-months today; day / week / 30d / 90d are rounded up to the
// smallest server timeframe that contains them.
func timeframeForRange(r RangeKey) string {
	switch r {
	case RangeDay, RangeWeek, Range30d, RangeMonth:
		return "last-month"
	case Range90d:
		return "last-3-months"
	}
	return "last-month"
}

// ContributorsFromMeRecap converts a RecapEndpointResponse into the
// ContributorsData shape the rest of the recap package consumes. This
// lets us drop in the new endpoint without changing downstream rendering.
func ContributorsFromMeRecap(resp *RecapEndpointResponse) *ContributorsData {
	if resp == nil || len(resp.Agents) == 0 {
		return nil
	}
	out := &ContributorsData{ByAgent: map[string]*AgentContrib{}}
	if resp.Repo != nil {
		out.Repo = *resp.Repo
	}
	for name, entry := range resp.Agents {
		if entry.Contributors == nil {
			continue
		}
		c := entry.Contributors
		distinctContribs := 0
		if resp.Contributors != nil {
			distinctContribs = resp.Contributors.DistinctUsers
		}
		agg := &AgentContrib{
			TotalCount:       c.Checkpoints,
			Tokens:           c.Tokens,
			DistinctContribs: distinctContribs,
			Skills:           flattenSkills(c.Skills),
			MCPServers:       flattenMCP(c.MCPServers),
			ToolMix:          toolMixToMap(c.ToolMix),
		}
		for _, l := range c.Labels {
			agg.Labels = append(agg.Labels, LabelCount{Label: l.Label, Count: l.Count})
		}
		out.ByAgent[name] = agg
	}
	return out
}

func flattenSkills(xs []RecapSkillCount) []string {
	out := make([]string, 0, len(xs))
	for _, x := range xs {
		out = append(out, x.Skill)
	}
	if len(out) > 3 {
		out = out[:3]
	}
	return out
}

func flattenMCP(xs []RecapMcpCount) []string {
	out := make([]string, 0, len(xs))
	for _, x := range xs {
		out = append(out, x.Name)
	}
	if len(out) > 3 {
		out = out[:3]
	}
	return out
}

func toolMixToMap(t RecapToolMix) map[string]int {
	return map[string]int{
		"shell":   t.Shell,
		"fileOps": t.FileOps,
		"search":  t.Search,
		"mcp":     t.MCP,
		"agent":   t.Agent,
		"other":   t.Other,
	}
}

// Suppress unused import when time is removed; keep the import path
// available for downstream helpers that may need it.
var _ = time.Second

