118	// "unknown" when the remote is absent or unparseable — never errors, since
119	// an unknown repo is a valid display state.
120	func ResolveRepoFromWorktree(ctx context.Context, worktreePath string) string {
121		if worktreePath == "" {
122			return repoUnknown
123		}
124		cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "remote", "get-url", "origin")
125		raw, err := cmd.Output()
126		if err != nil {
127			return repoUnknown
128		}
129		info, err := gitremote.ParseURL(strings.TrimSpace(string(raw)))
130		if err != nil || info == nil || info.Owner == "" || info.Repo == "" {
131			return repoUnknown
132		}
133		return info.Owner + "/" + info.Repo
134	}
