15	// RenderStatic produces the full static (non-TUI) recap output for a view.
16	// Width is the outer terminal width — the function clamps to a 60-cell
17	// minimum and uses the space for panel borders + content padding.
18	//
19	// Accessible / piped mode: pass styles from NewStyles(false). Output
20	// then contains no ANSI escapes and no Unicode borders; panels degrade to
21	// section headers separated by blank lines.
22	func RenderStatic(view View, styles Styles, width int) string {
23		if width < 60 {
24			width = 60
25		}
26		var b strings.Builder
27	
28		// Header bar: active range tab + agent filter + view mode. Present in
29		// both TUI and piped output so the reader always knows what's selected.
30		b.WriteString(renderHeader(view, "", styles))
31		b.WriteString("\n\n")
32	
33		// Panel 1: Summary band.
34		b.WriteString(renderPanel(view.Title, renderSummaryBand(view.Summary, styles), width, styles))
35		b.WriteString("\n\n")
36	
37		// Panel 2: Activity strip — range-dependent.
38		b.WriteString(renderActivityStrip(view, styles))
39		b.WriteString("\n\n")
40	
41		// Panel 3: Agents (default) or Sessions (fallback when view has no AgentCards).
42		if len(view.AgentCards) > 0 {
43			b.WriteString(renderPanel("Agents", renderAgentsView(view.AgentCards, view.Mode, styles), width, styles))
44		} else {
45			b.WriteString(renderPanel("Sessions", renderSessionList(view.Sessions, styles), width, styles))
46		}
47		b.WriteString("\n\n")
48	
49		// Panel 4: Repos · Worktrees · Labels (3-column bottom panel).
50		b.WriteString(renderBottomPanel(view, styles))
51	
52		// Diagnostic notes: "not logged in", "repo not tracked", etc. Only
53		// rendered when present so silent successful cases show no chrome.
54		if len(view.Notes) > 0 {
55			b.WriteString("\n\n")
56			for i, n := range view.Notes {
57				if i > 0 {
58					b.WriteString("\n")
59				}
60				b.WriteString(styles.muted.Render("  ℹ " + n))
61			}
62		}
63	
64		return b.String()
65	}
