67	func renderSummaryBand(s SummaryBand, styles Styles) string {
68		kv := func(label, value string) string {
69			return styles.label.Render(label) + "  " + styles.value.Render(value)
70		}
71	
72		// "Focus" = the one label that covers ≥55% of the range's checkpoints
73		// AND leads the runner-up by ≥15%. Empty when no label takes the lead
74		// cleanly, or when no labels are loaded yet (server analysis pending).
75		focus := placeholderDash
76		if s.DominantLabel != "" {
77			focus = fmt.Sprintf("▪ %s  %d%%", s.DominantLabel, int(s.DominantLabelPct*100))
78		} else if s.CheckpointCount > 0 {
79			focus = styles.muted.Render("(mixed)")
80		}
81	
82		topAgent := s.TopAgent
83		if topAgent == "" {
84			topAgent = placeholderDash
85		}
86		if s.AgentFilter != "" {
87			topAgent = styles.accent.Render("["+s.AgentFilter+"]") + " (filter)"
88		}
89		topSkill := placeholderDash // skill wiring lives in a later chunk; keep the slot visible
90		topModel := s.TopModel
91		if topModel == "" {
92			topModel = placeholderDash
93		}
94	
95		line1 := kv("Top agent", topAgent) + "  " + kv("Top skill", topSkill)
96		line2 := kv("Focus    ", focus) + "  " + kv("Top model", topModel)
97		totals := fmt.Sprintf("%d sessions · %d checkpoints · %s tokens · %d commits",
98			s.SessionCount, s.CheckpointCount, formatTokens(s.TokenTotal), s.CommitCount)
99		line3 := kv("Totals    ", totals)
100		return line1 + "\n" + line2 + "\n\n" + line3
101	}
