103	func renderActivityStrip(view View, styles Styles) string {
104		if len(view.Activity) == 0 {
105			return styles.muted.Render("  (no activity in range)")
106		}
107		var header string
108		switch view.Range {
109		case RangeDay:
110			header = "Activity (24h)"
111		case RangeWeek:
112			header = "Activity (7d)"
113		case RangeMonth:
114			header = "Activity (this month)"
115		case Range30d:
116			header = "Activity (30d)"
117		case Range90d:
118			header = "Activity (90d)"
119		default:
120			header = "Activity"
121		}
122	
123		if view.Range == RangeDay && len(view.Activity) == 24 {
124			var events [24]int
125			copy(events[:], view.Activity)
126			return styles.label.Render(header) + "\n" + renderIntraDayStrip(events, styles)
127		}
128		strip := renderHeatmapStrip(view.Activity, maxOf(view.Activity), styles)
129		labels := renderRangeAxisLabels(view.Range, len(view.Activity), styles)
130		return styles.label.Render(header) + "\n" + strip + "\n" + labels
131	}
