133	// renderRangeAxisLabels draws a second row of labels under the heatmap
134	// strip so multi-day ranges have context for each cell.
135	//   - week: M T W T F S S (one letter per day, aligned with cells)
136	//   - month/30d/90d: date markers every ~7 cells, formatted "Apr 1"
137	//
138	// All labels are styled with the muted grey so the heatmap row stays
139	// visually prominent.
140	func renderRangeAxisLabels(r RangeKey, cellCount int, styles Styles) string {
141		now := time.Now()
142		switch r { //nolint:exhaustive // RangeDay uses a different renderer (renderIntraDayStrip) with its own hour labels
143		case RangeWeek:
144			// 7 day-of-week initials, starting 7 days ago.
145			start := now.AddDate(0, 0, -6)
146			var out []rune
147			for i := 0; i < 7 && i < cellCount; i++ {
148				d := start.AddDate(0, 0, i)
149				initials := []rune{'M', 'T', 'W', 'T', 'F', 'S', 'S'}
150				// Go's Weekday enum is Sun=0..Sat=6; map to our index where M=0.
151				idx := (int(d.Weekday()) + 6) % 7
152				out = append(out, initials[idx])
153			}
154			return styles.muted.Render(string(out))
155		case RangeMonth, Range30d, Range90d:
156			// Date markers every 7 cells. Each marker occupies up to 6 characters;
157			// pad between markers so the next one lines up with its cell.
158			step := 7
159			if r == Range90d {
160				step = 14
161			}
162			start := now.AddDate(0, 0, -(cellCount - 1))
163			var out strings.Builder
164			written := 0
165			for i := 0; i < cellCount; i += step {
166				if i > written {
167					out.WriteString(strings.Repeat(" ", i-written))
168					written = i
169				}
170				label := start.AddDate(0, 0, i).Format("Jan 2")
171				out.WriteString(label)
172				written += len(label)
173			}
174			return styles.muted.Render(out.String())
175		}
176		return ""
177	}
