43	
44		// Cache lookup (version-agnostic — we trust any cached copy for the
45		// session; if pipeline_version bumps mid-session the next run will refetch).
46		if e.cache != nil {
47			if resp, ok := e.cache.Get(cpID); ok {
48				return merge(cp, resp), nil
49			}
50		}
51	
52		resp, err := e.fetch(ctx, cp.Repo, cpID)
53		if err != nil {
