55				"checkpoint", cpID, "error", err.Error())
56			return cp, nil // non-fatal
57		}
58		// Only "complete" responses carry usable analysis fields. Pending /
59		// generating / failed / not_available responses have zero-valued labels
60		// + toolProfile and would poison the cache (and the render) with
61		// blank rows. Skip merge and skip Put until the server has real data.
62		if !resp.IsComplete() {
63			logging.Debug(ctx, "recap: analysis not complete",
64				"checkpoint", cpID, "status", resp.Status)
65			return cp, nil
66		}
67		if e.cache != nil {
68			if putErr := e.cache.Put(cpID, resp); putErr != nil {
69				logging.Debug(ctx, "recap: cache put failed",
70					"checkpoint", cpID, "error", putErr.Error())
71			}
72		}
73		return merge(cp, resp), nil
74	}
